/** Conditional modules: `when` predicates over host facts (0001 §5).
 *  The `facts` object is populated by the eval runner after the host
 *  entrypoint; modules read it freely. */
import { currentFacts } from "./facts.js";
const auto = currentFacts();
let live = { os: auto.os, arch: auto.arch, libc: auto.libc, tags: auto.tags };
/** The shared host facts — set by the runner, read by modules. */
export const facts = {
    get os() {
        return live.os;
    },
    get arch() {
        return live.arch;
    },
    get libc() {
        return live.libc;
    },
    get tags() {
        return live.tags;
    },
};
/** True when the host declared `tag`. */
export function hasTag(tag) {
    return live.tags.includes(tag);
}
/** @internal Called by the eval runner once tags are known. */
export function setTags(tags) {
    live = { ...live, tags };
}
/** Build a condition over host facts — data style via `moduleIf` /
 *  `defineIf`, or evaluate directly: `when({ os: "linux" })`. */
export function when(cond) {
    if (cond.os !== undefined && live.os !== cond.os)
        return false;
    if (cond.arch !== undefined && live.arch !== cond.arch)
        return false;
    if (cond.libc !== undefined && live.libc !== cond.libc)
        return false;
    if (cond.tags?.some((t) => !live.tags.includes(t)))
        return false;
    if (cond.notTags?.some((t) => live.tags.includes(t)))
        return false;
    return true;
}
